def find_Max(A, start, end):
    if (start > end):
        return -1
    mid = int((start + end) / 2)
    if (mid < end and A[mid] > A[mid + 1]):
        return A[mid]
    if (mid > start and A[mid] < A[mid - 1]):
        return A[mid]
    if (A[start] > A[mid]):
        return find_Max(A, mid + 1, end)
    return find_Max(A, start, mid)
