def perfect_squares(l,r):
    result = []
    for i in range(l,l*r+1):
        if (i*i > r) : break
        if (i*i == r) : result.append(i)
        elif (i*i < r) : result.extend([i*(i+1)//2 for i in range(i+1,int(r/i)+1)]) 
    return result
