def find_kth(arr1, arr2, m, n, K):
    i = 0
    j = 0
    count = 0
    while (i < m and j < n):
        if (arr1[i] < arr2[j]):
            count += 1
            i += 1
        else:
            count += 1
            j += 1
        if (count == K):
            return arr1[i - 1]
    if (count == K - 1):
        return arr2[j - 1]
    if (count == 1):
        return min(arr1[i - 1], arr2[j - 1])
```

